<?php $id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);$sql='SELECT o.*,u.full_name cashier FROM orders o JOIN users u ON u.id=o.user_id WHERE o.id=?';$args=[$id];if(!is_admin()){$sql.=' AND o.user_id=?';$args[]=current_user()['id'];}$q=db()->prepare($sql);$q->execute($args);$order=$q->fetch();if(!$order){http_response_code(404);?><div class="empty-state"><strong>Nota tidak ditemukan</strong><p>Pesanan ini tidak tersedia untuk akun Anda.</p><a href="index.php?page=orders">Kembali ke daftar pesanan</a></div><?php }else{$q=db()->prepare('SELECT * FROM order_details WHERE order_id=?');$q->execute([$id]);$lines=$q->fetchAll();?>
<div class="page-heading no-print"><div><p class="eyebrow">TRANSAKSI TERSIMPAN</p><h1>Pesanan berhasil dicatat</h1><p class="subheading">Nota siap dicetak atau disimpan sebagai PDF.</p></div><a class="button quiet" href="index.php?page=orders">Ke daftar pesanan</a></div><div class="receipt-actions no-print"><button class="button primary" onclick="window.print()">Cetak nota</button><a class="button quiet" href="index.php?page=new-order">＋ Pesanan berikutnya</a></div><article class="receipt"><div class="receipt-brand"><div class="brand-mark">tt</div><div><h2>Titik Temu Kopi</h2><p>Tempat singgah, cerita bertemu.</p></div></div><div class="receipt-title"><span>BUKTI PEMBAYARAN</span><span class="status <?= $order['status']==='Selesai'?'done':($order['status']==='Dibatalkan'?'cancelled':'pending') ?>"><?= e($order['status']) ?></span></div><div class="receipt-meta"><div><span>No. invoice</span><strong><?= e($order['invoice_number']) ?></strong></div><div><span>Tanggal</span><strong><?= date('d/m/Y H:i',strtotime($order['created_at'])) ?> WIB</strong></div><div><span>Kasir</span><strong><?= e($order['cashier']) ?></strong></div><div><span>Tipe</span><strong><?= e($order['order_type']) ?><?= $order['table_number']?' · Meja '.$order['table_number']:'' ?></strong></div><?php if($order['customer_name']):?><div><span>Pemesan</span><strong><?= e($order['customer_name']) ?></strong></div><?php endif;?></div><div class="receipt-lines"><div class="receipt-line receipt-line-head"><span>Menu</span><span>Jumlah</span><span>Harga</span></div><?php foreach($lines as $line):?><div class="receipt-line"><span><strong><?= e($line['product_name']) ?></strong><?php if($line['special_note']):?><small><?= e($line['special_note']) ?></small><?php endif;?></span><span><?= (int)$line['quantity'] ?> ×</span><span><?= rupiah($line['line_subtotal']) ?></span></div><?php endforeach;?></div><div class="receipt-totals"><div><span>Subtotal</span><strong><?= rupiah($order['subtotal']) ?></strong></div><div><span>Diskon</span><strong>− <?= rupiah($order['discount_amount']) ?></strong></div><div><span>PB1 (10%)</span><strong><?= rupiah($order['tax_amount']) ?></strong></div><div class="receipt-grand"><span>Total</span><strong><?= rupiah($order['grand_total']) ?></strong></div><div><span><?= e($order['payment_method']) ?> · dibayar</span><strong><?= rupiah($order['amount_paid']) ?></strong></div><?php if($order['payment_method']==='Tunai'):?><div><span>Kembalian</span><strong><?= rupiah($order['change_amount']) ?></strong></div><?php endif;?></div><p class="receipt-thanks">Terima kasih sudah singgah.<br>Sampai jumpa kembali.</p></article><?php }?>
